{"file_path":"/tmp/bot-p622r2-dev/work/dev-single-json-schema-1/validate.mjs","content":"// validate.mjs — 校验样例配置的 port 与 enabled 字段
// 运行：node validate.mjs
// 任何一项校验失败时以非零退出码（1）退出。

const sample = { "port": 8080, "enabled": true };

const checks = [
  {
    name: "port",
    description: "port 是整数且在 1–65535 范围内的合法端口",
    run: (data) =>
      Number.isInteger(data.port) && data.port >= 1 && data.port <= 65535,
  },
  {
    name: "enabled",
    description: "enabled 是布尔值（typeof === 'boolean'）",
    run: (data) => typeof data.enabled === "boolean",
  },
];

console.log(`样例数据: ${JSON.stringify(sample)}`);
console.log("---");

let allPassed = true;

for (const check of checks) {
  const passed = check.run(sample);
  console.log(
    `[${passed ? "PASS" : "FAIL"}] ${check.name}: ${check.description} => 实际值 ${
      JSON.stringify(sample[check.name])
    } (${typeof sample[check.name]})`
  );
  if (!passed) allPassed = false;
}

console.log("---");
if (allPassed) {
  console.log("总体结论: 全部校验通过");
  process.exit(0);
} else {
  console.log("总体结论: 存在校验失败项");
  process.exit(1);
}
"}

